def clean_readings(readings):
    result = []
    for i in range(len(readings)):
        if readings[i] > 0:
            result.append(readings[i])
    return result

def latest_by_id(rows):
    best = {}
    for r in rows:
        cur = best.get(r["id"])
        if cur is None or r["updated_at"] < cur["updated_at"]:
            best[r["id"]] = r
    return sorted(best.values(), key=lambda r: r["id"])

