def drop_empty(record):
    for k in record:
        if record[k] in (None, ""):
            del record[k]
    return record

def fetch_with_retry(fetch, tries=3):
    for attempt in range(tries):
        try:
            return fetch()
        except Exception:
            if attempt == tries:
                raise
    return None

